function TURAN_BOUNDS(n, r):
    require r >= 1
    real_bound <- (1 - 1/r) * n^2 / 2
    return real_bound

function TURAN_INT_HOLDS(n, r, e):
    return 2*r*e <= (r-1)*n^2

function KK_EDGE_LB(T, n):
    lo <- 3; hi <- n; best <- 2
    while lo <= hi:
        mid <- (lo + hi) // 2
        if C(mid,3) <= T:
            best <- mid; lo <- mid + 1
        else:
            hi <- mid - 1
    return (best, C(best,2))

function AP_TRIANGLE_COUNT(A, n):
    count <- 0
    for x in A:
        for d in 1..max(A):
            if (x+d) in A and (x+2d) in A:
                count <- count + 1
    return count
